import { chromium } from '@playwright/test'

const BASE = process.env.BASE ?? 'http://127.0.0.1:3100'
const browser = await chromium.launch()

for (const vp of [{ width: 1440, height: 900 }, { width: 390, height: 844 }]) {
  const ctx = await browser.newContext({ viewport: vp })
  const page = await ctx.newPage()
  const requested = new Set()
  page.on('request', (r) => {
    if (r.url().includes('/_next/image')) requested.add(decodeURIComponent(r.url()))
  })
  await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(2500)

  const info = await page.evaluate((vh) => {
    const docH = document.documentElement.scrollHeight
    const imgs = [...document.querySelectorAll('img')].map((img, i) => ({
      i,
      top: Math.round(img.getBoundingClientRect().top + window.scrollY),
      loading: img.loading,
      // currentSrc is empty until the browser actually fetches it
      fetched: Boolean(img.currentSrc),
    }))
    return { docH, vh, imgs }
  }, vp.height)

  const fetched = info.imgs.filter((i) => i.fetched)
  const belowFold = fetched.filter((i) => i.top > vp.height)
  const deepest = fetched.length ? Math.max(...fetched.map((i) => i.top)) : 0

  console.log(`\n=== ${vp.width}x${vp.height} ===`)
  console.log(`document height: ${info.docH}px  (${(info.docH / vp.height).toFixed(1)} viewports)`)
  console.log(`images: ${info.imgs.length} total, ${fetched.length} fetched`)
  console.log(`  fetched below the fold: ${belowFold.length}`)
  console.log(`  deepest fetched image starts at y=${deepest}px, i.e. ${(deepest / vp.height).toFixed(1)} viewports down`)
  console.log(`  optimiser requests seen: ${requested.size}`)
  const notFetched = info.imgs.filter((i) => !i.fetched)
  if (notFetched.length) {
    console.log(`  NOT fetched: ${notFetched.length}, shallowest of them at y=${Math.min(...notFetched.map((i) => i.top))}px`)
  }
  await ctx.close()
}

await browser.close()

