"use client";

import Image from "next/image";
import clsx from "clsx";
import { useEffect, useRef, useState } from "react";

type Props = {
  src: string;
  alt: string;
  sizes: string;
  className?: string;
  /**
   * Render the image straight away, server-side and in the HTML. For cards at
   * or near the first screen, where deferring buys nothing and costs a frame.
   */
  eager?: boolean;
};

/**
 * How far ahead of the viewport to start fetching.
 *
 * Chrome's own `loading="lazy"` threshold measured at roughly 3900px here,
 * which is what #230 is about: at 1440x900 that reaches 4.3 viewports down and
 * pulls in 18 of the home page's 20 cards. 600px is a little under a viewport
 * on a laptop and about three quarters of one on a phone -- far enough that an
 * ordinary scroll reaches a decoded image rather than a gap, near enough that
 * the page is not optimising screens nobody has asked for.
 */
const ROOT_MARGIN = "600px";

/**
 * A product-card image that is fetched when it is nearly on screen.
 *
 * `loading="lazy"` is a hint about a threshold the browser picks, not a
 * viewport test, and the threshold it picks is far too generous for a page
 * carrying twenty separately-optimised images. This narrows it.
 *
 * The trade is that a deferred image is not in the server-rendered HTML, so
 * without JavaScript it would never arrive. The `<noscript>` fallback covers
 * that with the unoptimised source -- heavier than the optimiser's variant, and
 * correct, which is the right way round for a case this rare.
 */
export default function ListingImage({
  src,
  alt,
  sizes,
  className,
  eager = false,
}: Props) {
  const [show, setShow] = useState(eager);
  const placeholder = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (show) return;
    const node = placeholder.current;
    if (!node) return;

    // No observer means no way to tell when this is needed, so show it rather
    // than leave a permanent gap. Old browsers get today's behaviour back.
    if (typeof IntersectionObserver === "undefined") {
      setShow(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) return;
        setShow(true);
        observer.disconnect();
      },
      { rootMargin: ROOT_MARGIN },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [show]);

  if (show) {
    return (
      <Image
        src={src}
        alt={alt}
        width={350}
        height={350}
        sizes={sizes}
        className={className}
      />
    );
  }

  return (
    <div
      ref={placeholder}
      // Square, because that is what the image will be: reserving the box keeps
      // the cards below from moving when it arrives, and keeps the document
      // height honest so the observer's own margin means what it says.
      className={clsx(className, "aspect-square w-full bg-zinc-100")}
    >
      <noscript>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={src} alt={alt} className={className} />
      </noscript>
    </div>
  );
}

