/**
 * #180's measurement, reproduced.
 *
 * Throttling matches the issue: 1.6 Mbps down, 150ms RTT, 4x CPU. Without it
 * every card lands in double digits of ms on this machine and the artifact the
 * issue describes cannot exist at all.
 *
 * Reports, per run: when each above-fold card's image finished, and the LCP
 * the page reported. Medians are taken across runs by the caller.
 */
import { chromium } from '@playwright/test'

const BASE = process.env.BASE ?? 'http://localhost:3100'
const PATH = '/products/category/tents'
const RUNS = Number(process.env.RUNS ?? 5)

const VIEWPORTS = [
  { width: 390, height: 844, name: '390' },
  { width: 834, height: 1112, name: '834' },
  { width: 1440, height: 900, name: '1440' },
]

const median = (xs) => {
  const s = [...xs].sort((a, b) => a - b)
  return s.length % 2 ? s[(s.length - 1) / 2] : Math.round((s[s.length / 2 - 1] + s[s.length / 2]) / 2)
}

const browser = await chromium.launch()

for (const vp of VIEWPORTS) {
  const perCard = new Map()
  const lcps = []

  for (let run = 0; run < RUNS; run++) {
    const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height } })
    const page = await ctx.newPage()
    const cdp = await ctx.newCDPSession(page)
    await cdp.send('Network.enable')
    await cdp.send('Network.emulateNetworkConditions', {
      offline: false,
      latency: 150,
      downloadThroughput: (1.6 * 1024 * 1024) / 8,
      uploadThroughput: (750 * 1024) / 8,
    })
    await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 })

    await page.addInitScript(() => {
      window.__lcp = 0
      new PerformanceObserver((l) => {
        for (const e of l.getEntries()) window.__lcp = e.startTime
      }).observe({ type: 'largest-contentful-paint', buffered: true })
    })

    const t0 = Date.now()
    const finished = new Map()
    page.on('requestfinished', (r) => {
      if (r.url().includes('/_next/image')) finished.set(r.url(), Date.now() - t0)
    })

    await page.goto(BASE + PATH, { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(9000)

    const cards = await page.evaluate(() => {
      const boxes = [...document.querySelectorAll('a[href^="/products/"] div.aspect-square')]
      return boxes.map((box, index) => {
        const rect = box.getBoundingClientRect()
        const img = box.querySelector('img')
        return {
          index,
          onScreen: rect.top < window.innerHeight && rect.bottom > 0,
          visiblePx: Math.round(Math.min(rect.bottom, window.innerHeight) - Math.max(rect.top, 0)),
          src: img?.currentSrc ?? null,
          complete: Boolean(img && img.complete && img.naturalWidth > 0),
        }
      })
    })

    lcps.push(Math.round(await page.evaluate(() => window.__lcp)))
    for (const card of cards.filter((c) => c.onScreen)) {
      const ms = card.src ? finished.get(card.src) ?? null : null
      if (!perCard.has(card.index)) perCard.set(card.index, { visiblePx: card.visiblePx, times: [] })
      if (ms !== null) perCard.get(card.index).times.push(ms)
    }
    await ctx.close()
  }

  console.log(`\n=== ${vp.width}x${vp.height} (median of ${RUNS}, 1.6Mbps/150ms/4x CPU) ===`)
  console.log(`  LCP: ${median(lcps)}ms`)
  const rows = [...perCard.entries()].sort((a, b) => a[0] - b[0])
  for (const [index, data] of rows) {
    const m = data.times.length ? `${median(data.times)}ms` : 'never'
    console.log(`  card index ${index} (${String(data.visiblePx).padStart(4)}px visible): ${m}`)
  }
  if (rows.length > 1) {
    const times = rows.filter(([, d]) => d.times.length).map(([, d]) => median(d.times))
    if (times.length > 1) {
      console.log(`  spread across the visible cards: ${Math.max(...times) - Math.min(...times)}ms`)
    }
  }
}

await browser.close()

