/**
 * #273 on both surfaces: does `content-visibility: auto` defer as well as the
 * JavaScript mechanism, and what does a fast fling look like?
 *
 * The fling matters because the two mechanisms fail differently. A deferred
 * image that arrives late is a network wait, which `rootMargin` was tuned
 * against. A skipped subtree has to *render* on approach — layout and paint,
 * not a fetch — so the failure is an unpainted card rather than a grey one,
 * and no margin governs it.
 */
import { chromium } from '@playwright/test'

const BASE = process.env.BASE ?? 'http://localhost:3100'
const CPU = Number(process.env.CPU ?? 4)
const LABEL = process.env.LABEL ?? 'run'

const SURFACES = [
  { name: 'home', path: '/' },
  { name: 'category', path: '/products/category/tents' },
]
const VIEWPORTS = [
  { width: 390, height: 844 },
  { width: 834, height: 1112 },
  { width: 1440, height: 900 },
]

const CARD = 'a[href^="/products/"]:not([href^="/products/category/"])'

const browser = await chromium.launch()

for (const surface of SURFACES) {
  for (const vp of VIEWPORTS) {
    const ctx = await browser.newContext({ viewport: vp })
    const page = await ctx.newPage()
    const cdp = await ctx.newCDPSession(page)
    await cdp.send('Emulation.setCPUThrottlingRate', { rate: CPU })
    await page.addInitScript(() => {
      window.__cls = 0
      new PerformanceObserver((l) => {
        for (const e of l.getEntries()) if (!e.hadRecentInput) window.__cls += e.value
      }).observe({ type: 'layout-shift', buffered: true })
    })

    const requested = new Set()
    page.on('request', (r) => {
      if (r.url().includes('/_next/image')) requested.add(r.url())
    })

    await page.goto(BASE + surface.path, { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(3000)

    const initial = requested.size
    const shape = await page.evaluate((sel) => ({
      cards: document.querySelectorAll(sel).length,
      docH: document.documentElement.scrollHeight,
      // Every image is in the HTML under this mechanism; count them to prove it.
      imgs: document.querySelectorAll(`${sel} img`).length,
    }), CARD)

    // Fling: jump a viewport at a time as fast as the page will take it, and
    // sample what is on screen immediately, before anything can settle.
    let worstBlank = 0
    const steps = Math.ceil(shape.docH / vp.height)
    for (let i = 1; i <= steps; i++) {
      await page.evaluate((y) => window.scrollTo(0, y), i * vp.height)
      const blank = await page.evaluate((sel) => {
        const boxes = [...document.querySelectorAll(`${sel} div.aspect-square`)]
        return boxes.filter((box) => {
          const r = box.getBoundingClientRect()
          if (!(r.top < window.innerHeight && r.bottom > 0)) return false
          const img = box.querySelector('img')
          return !(img && img.complete && img.naturalWidth > 0)
        }).length
      }, CARD)
      if (blank > worstBlank) worstBlank = blank
    }

    const settled = await page.evaluate(() => ({
      docH: document.documentElement.scrollHeight,
      cls: window.__cls,
    }))

    console.log(
      `${LABEL} ${surface.name.padEnd(8)} ${String(vp.width).padStart(4)}x${vp.height}: ` +
      `${String(initial).padStart(2)}/${shape.cards} initial | imgs in DOM ${shape.imgs}/${shape.cards} | ` +
      `worst blank on fling ${worstBlank} | docH ${shape.docH}${settled.docH === shape.docH ? '' : ' -> ' + settled.docH} | ` +
      `CLS ${settled.cls.toFixed(4)}`,
    )
    await ctx.close()
  }
}

await browser.close()

import Image from "next/image";

type Props = {
  src: string;
  alt: string;
  sizes: string;
};

/**
 * The home grid's product image, in a box the browser is free to skip.
 *
 * `loading="lazy"` is not a viewport test. Chrome fetches lazy images within a
 * threshold measured at roughly 3900px, which at 1440x900 reaches 4.3
 * viewports down a 5038px document and pulled in 18 of the page's 20 images
 * before any scrolling. Each is a separate `sharp` decode-and-resize, and on a
 * two-core runner they measured a median of 2343ms each — enough that an
 * unrelated navigation issued during them went from 78ms to 500ms, and enough
 * to abort one outright in CI. See #230.
 *
 * `content-visibility: auto` fixes that without JavaScript: the browser skips
 * rendering a subtree that is off screen, and does not fetch images inside a
 * skipped subtree. Measured on this page, initial optimiser requests go 18 →
 * 9 at desktop, 16 → 12 at tablet and 7 → 5 at phone, with the document height
 * unchanged at every width and CLS 0.0000 through a full scroll.
 *
 * **This replaced an IntersectionObserver that did the same job.** The
 * observer worked, and matched these numbers, but a deferred image was not in
 * the server-rendered HTML — so a blocked script chunk left permanent empty
 * boxes with no `<noscript>` recourse (#261), a card on the first screen had
 * to wait for hydration before it could even be requested, and the fallback
 * for scripting-off cost about 12x the optimised bytes. Every one of those is
 * a consequence of deciding in JavaScript what the browser will decide for
 * itself. Measured side by side, the two are indistinguishable on request
 * counts and on blank cards during a fast fling; they differ only in that
 * every image here is in the HTML. See #273.
 *
 * No `contain-intrinsic-size`: the box is `aspect-square w-full`, so its size
 * comes from CSS rather than from its contents and holds while the subtree is
 * skipped. A size hint would only matter for a box that sizes to what is
 * inside it.
 *
 * `aspect-square` is an observation about the catalogue, not something held:
 * every one of the 853 sources is 1024x1024 today, but the encoding contract
 * bounds only the long edge, so a 1024x600 would letterbox here with nothing
 * turning red. See #262.
 */
export default function ListingImage({ src, alt, sizes }: Props) {
  return (
    <div className="aspect-square w-full overflow-hidden rounded-3xl bg-zinc-200 [content-visibility:auto]">
      <Image
        src={src}
        alt={alt}
        width={350}
        height={350}
        sizes={sizes}
        // w-full so the image scales into the box; h-auto because the source is
        // square and so fills a square box exactly. See #262.
        className="w-full h-auto"
      />
    </div>
  );
}

